"""并查集（路径减半压缩 + 按秩合并）与 lc200 岛屿数量。

与人工 referenceSolution 同一算法路径：
  DSU.__init__ : p = list(range(n))、rank = [0]*n、count = n
  find         : 迭代式路径减半 self.p[x] = self.p[self.p[x]]
  union        : rank 小的根挂到 rank 大的根；等高才 rank[新根] += 1；成功合并才 count -= 1
  num_islands  : 二维坐标压成一维 id = r*C + c，每个 '1' 只与左、上邻居 union
纯 Python 标准库实现，不需要 torch / numpy（图形无关的数据结构题）。
本文件额外加了：下标/形状校验、connected() 便捷方法、以及一段可运行的 _self_test。
"""


class DSU:
    """路径减半压缩 + 按秩合并：单次操作均摊近似 O(alpha(n))。"""

    def __init__(self, n):
        if n < 0:
            raise ValueError('元素个数不能为负: %r' % (n,))
        self.p = list(range(n))     # 父指针；根满足 p[x] == x
        self.rank = [0] * n         # 树高（rank）上界，只增不减
        self.count = n              # 连通分量个数：初值 n，成功合并才减 1

    def find(self, x):
        """返回 x 所在树的根，顺手把路径减半。迭代写法，不吃递归深度。"""
        if not 0 <= x < len(self.p):
            raise IndexError('find 下标越界: %r' % (x,))
        while self.p[x] != x:
            self.p[x] = self.p[self.p[x]]   # 指向祖父：走过的路径大约减半
            x = self.p[x]
        return x

    def union(self, a, b):
        """合并 a、b 所在集合；返回 True 表示这次真的合并了两个分量。"""
        ra, rb = self.find(a), self.find(b)
        if ra == rb:
            return False                    # 已在同一集合：count 不能再减
        if self.rank[ra] < self.rank[rb]:
            ra, rb = rb, ra                 # 保证 ra 是更高的那棵树的根
        self.p[rb] = ra                     # 矮树挂到高树根下
        if self.rank[ra] == self.rank[rb]:
            self.rank[ra] += 1              # 只有等高时新树高才 +1
        self.count -= 1
        return True

    def connected(self, a, b):
        return self.find(a) == self.find(b)


def num_islands(grid):
    """lc200：grid 是 R 行 C 列字符矩阵，'1' 陆地 / '0' 水；返回岛的个数。"""
    if not grid or not grid[0]:
        return 0                                # [] 与 [[]] 两个边界
    R, C = len(grid), len(grid[0])
    dsu = DSU(R * C)
    ones = 0
    for r in range(R):
        if len(grid[r]) != C:
            raise ValueError('第 %d 行 %d 列，首行 %d 列（锯齿矩阵）' % (r, len(grid[r]), C))
        for c in range(C):
            if grid[r][c] != '1':
                continue                        # '0' 不 union，也不计入 ones
            ones += 1
            for dr, dc in ((0, -1), (-1, 0)):   # 只看左、上：每条边只处理一次
                nr, nc = r + dr, c + dc
                if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == '1':
                    dsu.union(r * C + c, nr * C + nc)
    roots = {dsu.find(r * C + c) for r in range(R) for c in range(C) if grid[r][c] == '1'}
    # 等价读数：每个 '0' 格子仍是独立分量，故 k = count - (R*C - ones)。
    assert len(roots) == dsu.count - (R * C - ones), 'k 的两种算法应当一致'
    return len(roots)


def _self_test():
    cases = [
        ([], 0),
        ([[]], 0),
        (['0'], 0),
        (['1'], 1),
        (['111', '010', '111'], 1),                  # 环：少写一个方向就会算成 5
        (['11000', '11000', '00100', '00011'], 3),   # lc200 官方样例
        (['111', '111', '111'], 1),
        (['101', '010', '101'], 5),                  # 对角不算连通
    ]
    for grid, want in cases:
        got = num_islands(grid)
        assert got == want, 'grid=%r 期望 %d 实得 %d' % (grid, want, got)

    dsu = DSU(10)
    assert dsu.find(0) == 0
    for i in range(1, 10):
        dsu.union(i - 1, i)                          # 0-1-2-...-9：全并成一个分量
    assert dsu.count == 1 and dsu.connected(0, 9)

    chain = DSU(6)
    for i in range(5):
        chain.p[i] = i + 1                           # 手工造 0->1->2->3->4->5 的链
    assert chain.find(0) == 5
    assert chain.p[0] != 1, '路径减半后 0 应指向祖父，而不是仍指向父节点'
    print('自测通过：%d 组岛屿用例 + DSU 连通性 + 路径减半验证' % len(cases))


if __name__ == '__main__':
    _self_test()
